-- Zaypoll three-level topic seed
-- Generated for MySQL 8.x. Safe to rerun by unique slug.
-- Existing matching slugs are reactivated and synchronized; is_trending is preserved.

START TRANSACTION;

-- Level 1: main categories

-- Level 2: topic groups

-- Level 3: specific topics

COMMIT;

-- Verification: expected counts by depth
SELECT
  CASE
    WHEN p.id IS NULL THEN 1
    WHEN gp.id IS NULL THEN 2
    ELSE 3
  END AS topic_level,
  COUNT(*) AS topic_count
FROM topics t
LEFT JOIN topics p ON p.id = t.parent_id
LEFT JOIN topics gp ON gp.id = p.parent_id
GROUP BY topic_level
ORDER BY topic_level;